import numpy as np
from collections import Counter
def read(f):
    L=open(f).read().split('\n'); n=int(L[0]); at=[]
    for l in L[2:2+n]:
        p=l.split(); at.append((p[0],np.array(list(map(float,p[1:4])))))
    return at
at=read('s6.xyz'); P=np.array([a[1] for a in at]); S=[a[0] for a in at]
def d(i,j): return np.linalg.norm(P[i]-P[j])
RCOV={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Cl':1.02,'Ge':1.21,'Ir':1.90}
n=len(at); D=np.linalg.norm(P[:,None,:]-P[None,:,:],axis=-1)
bond=np.zeros((n,n),bool)
for i in range(n):
    for j in range(i+1,n):
        if D[i,j]<RCOV[S[i]]+RCOV[S[j]]+0.45: bond[i,j]=bond[j,i]=True
seen=set(); frags=0
for s in range(n):
    if s in seen: continue
    frags+=1; stack=[s]
    while stack:
        u=stack.pop()
        if u in seen: continue
        seen.add(u)
        for v in np.where(bond[u])[0]:
            if v not in seen: stack.append(v)
print('fragments',frags)
expval={'H':1,'C':4,'N':3,'Ge':4,'Cl':1,'P':3}
prob=[]
for i in range(n):
    nb=[int(k) for k in np.where(bond[i])[0]]
    if S[i]=='Ir':
        print('Ir',i,'coord:',[(S[k],k,round(d(i,k),2)) for k in nb])
        continue
    e=expval[S[i]]
    if S[i]=='Cl' and len(nb)==2: continue  # bridging? shouldn't exist now
    if len(nb)!=e: prob.append((i,S[i],len(nb),nb))
print('valence problems:',prob)
print('Ge shell:',[(S[k],round(d(0,k),2)) for k in np.where(bond[0])[0]])
print('N shell:',[(S[k],round(d(1,k),2)) for k in np.where(bond[1])[0]])
print('P shell:',[(S[k],round(d(2,k),2)) for k in np.where(bond[2])[0]])
print('formula:',dict(Counter(S)))
